// Command generate-log-components generates the list of log components from the
// logger.RegisterComponent calls in the code base. The generated file is not a
// document of its own, it is included into doc/reference/settings.md.
package main

import (
	"bytes"
	"fmt"
	"go/ast"
	"go/parser"
	"go/token"
	"io/fs"
	"maps"
	"os"
	"path/filepath"
	"slices"
	"strconv"
	"strings"
)

const (
	outputPath = "doc/reference/settings_log_components.md"

	registerFuncName = "RegisterComponent"
)

// skippedDirs are not part of the daemon, so components registered there are
// not configurable.
var skippedDirs = []string{".git", "doc", "e2e_tests", "ui"}

func main() {
	err := run()
	if err != nil {
		fmt.Fprintf(os.Stderr, "generate-log-components: %v\n", err)
		os.Exit(1)
	}
}

func run() error {
	components, err := collectComponents(".")
	if err != nil {
		return err
	}

	if len(components) == 0 {
		return fmt.Errorf("No %s call found, the code base can not be without log components", registerFuncName)
	}

	return os.WriteFile(outputPath, render(components), 0o644)
}

// collectComponents returns the names passed to RegisterComponent in the go
// files below root, in lexical order and without duplicates.
func collectComponents(root string) ([]string, error) {
	seen := map[string]struct{}{}

	err := filepath.WalkDir(root, func(path string, d fs.DirEntry, err error) error {
		if err != nil {
			return err
		}

		if d.IsDir() {
			if path != root && slices.Contains(skippedDirs, d.Name()) {
				return fs.SkipDir
			}

			return nil
		}

		// Test files register components of their own, which are not part of
		// the daemon.
		if !strings.HasSuffix(path, ".go") || strings.HasSuffix(path, "_test.go") {
			return nil
		}

		names, err := componentsInFile(path)
		if err != nil {
			return err
		}

		for _, name := range names {
			seen[name] = struct{}{}
		}

		return nil
	})
	if err != nil {
		return nil, err
	}

	return slices.Sorted(maps.Keys(seen)), nil
}

func componentsInFile(path string) ([]string, error) {
	fileSet := token.NewFileSet()

	file, err := parser.ParseFile(fileSet, path, nil, 0)
	if err != nil {
		return nil, fmt.Errorf("Failed to parse %q: %w", path, err)
	}

	var (
		names   []string
		skipped []string
	)

	ast.Inspect(file, func(node ast.Node) bool {
		call, ok := node.(*ast.CallExpr)
		if !ok || len(call.Args) != 1 {
			return true
		}

		if !isRegisterComponent(call.Fun) {
			return true
		}

		// A name which is not a plain string literal can not be resolved here,
		// and silently leaving the component out would make the reference
		// incomplete without anybody noticing.
		lit, ok := call.Args[0].(*ast.BasicLit)
		if !ok || lit.Kind != token.STRING {
			skipped = append(skipped, fileSet.Position(call.Pos()).String())

			return true
		}

		name, err := strconv.Unquote(lit.Value)
		if err != nil {
			skipped = append(skipped, fileSet.Position(call.Pos()).String())

			return true
		}

		names = append(names, name)

		return true
	})

	if len(skipped) > 0 {
		return nil, fmt.Errorf("%s is called with something other than a string literal at %s, extend this generator to resolve it", registerFuncName, strings.Join(skipped, ", "))
	}

	return names, nil
}

// isRegisterComponent reports whether expr calls RegisterComponent, either
// qualified as logger.RegisterComponent or unqualified inside the logger
// package itself.
func isRegisterComponent(expr ast.Expr) bool {
	switch fun := expr.(type) {
	case *ast.SelectorExpr:
		return fun.Sel.Name == registerFuncName

	case *ast.Ident:
		return fun.Name == registerFuncName
	}

	return false
}

func render(components []string) []byte {
	buf := &bytes.Buffer{}

	fmt.Fprint(buf, `<!-- Code generated by generate-log-components; DO NOT EDIT. -->

This is the complete list of the components the daemon registers, grouped by
their top level. A level configured for a component applies to all of its
children as well, so a top level name is enough to cover everything below it.
`)

	group := ""

	for _, component := range components {
		topLevel, _, _ := strings.Cut(component, ".")
		if topLevel != group {
			group = topLevel

			fmt.Fprintf(buf, "\n%s:\n\n", topLevel)
		}

		fmt.Fprintf(buf, "- `%s`\n", component)
	}

	return buf.Bytes()
}
